"""Generate docs/results.md from cases/*/case.yaml."""
import argparse
from pathlib import Path

import yaml

STATUSES = ["planned", "win", "mixed", "fail", "manual"]
REQUIRED = ["title", "slug", "status", "stack", "tools", "models", "iterations", "time_spent_hours"]
HEADER = (
    "# Results\n\n"
    "Generated by make results from cases/*/case.yaml. Do not edit by hand.\n\n"
    "| Case | Status | Stack | Models | Iterations | Hours |\n"
    "|------|--------|-------|--------|------------|-------|\n"
)


def load(path):
    try:
        data = yaml.safe_load(path.read_text())
    except yaml.YAMLError as exc:
        raise SystemExit(f"{path}: invalid YAML: {exc}")
    if not isinstance(data, dict):
        raise SystemExit(f"{path}: expected a mapping")
    missing = [k for k in REQUIRED if k not in data or data[k] is None]
    if missing:
        raise SystemExit(f"{path}: missing required field(s): {', '.join(missing)}")
    if data["status"] not in STATUSES:
        raise SystemExit(f"{path}: invalid status '{data['status']}' (valid: {', '.join(STATUSES)})")
    return data


def cell(value):
    return str(value).replace("|", "\\|").replace("\n", " ")


def run(root):
    root = Path(root)
    cases = [load(p) for p in sorted((root / "cases").glob("*/case.yaml"))]
    cases.sort(key=lambda c: str(c["title"]).lower())
    out = HEADER
    for c in cases:
        models = ", ".join(str(m) for m in c["models"])
        out += (
            f"| [{cell(c['title'])}](cases/{c['slug']}/case-report.md) | {c['status']} | "
            f"{cell(c['stack'])} | {cell(models)} | {c['iterations']} | {c['time_spent_hours']} |\n"
        )
    counts = ", ".join(f"{s}: {sum(1 for c in cases if c['status'] == s)}" for s in STATUSES)
    out += f"\n**Total: {len(cases)}** ({counts})\n"
    target = root / "docs" / "results.md"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(out)
    return out


def main():
    argparse.ArgumentParser(description=__doc__).parse_args()
    run(Path(__file__).resolve().parent.parent)
    print("wrote docs/results.md")


if __name__ == "__main__":
    main()
